`ifndef SRAMC_SCOREBOARD_SV
`define SRAMC_SCOREBOARD_SV

class sramc_scoreboard extends uvm_component;

  `uvm_component_utils(sramc_scoreboard)

  // The scoreboard receives the actual monitor stream and the independent
  // expected-read stream generated by sramc_reference_model.
  uvm_tlm_analysis_fifo #(ahb_seq_item) observed_transfer_fifo;
  uvm_tlm_analysis_fifo #(ahb_seq_item) expected_read_fifo;
  int unsigned write_beat_count;
  int unsigned read_beat_count;
  int unsigned matched_beat_count;
  int unsigned mismatched_beat_count;

  extern function new(string name, uvm_component parent);
  extern task run_phase(uvm_phase phase);
  extern task get_and_check();
  extern function void compare(ahb_seq_item actual, ahb_seq_item expected);
  extern function void normalize_single_beat(ahb_seq_item transfer);
  extern function void report_phase(uvm_phase phase);

endclass : sramc_scoreboard


function sramc_scoreboard::new(string name, uvm_component parent);
  super.new(name, parent);
  observed_transfer_fifo = new("observed_transfer_fifo", this);
  expected_read_fifo     = new("expected_read_fifo", this);
endfunction : new


task sramc_scoreboard::run_phase(uvm_phase phase);
  forever get_and_check();
endtask : run_phase


task sramc_scoreboard::get_and_check();
  ahb_seq_item actual;
  ahb_seq_item expected;

  observed_transfer_fifo.get(actual);
  normalize_single_beat(actual);
  `uvm_info(get_full_name(),
            $sformatf("scoreboard got actual transaction:\n%s", actual.sprint()),
            UVM_HIGH)

  if (actual.direction == WRITE) begin
    write_beat_count += actual.beat_addr_q.size();
  end
  else begin
    expected_read_fifo.get(expected);
    normalize_single_beat(expected);
    compare(actual, expected);
  end
endtask : get_and_check


function void sramc_scoreboard::normalize_single_beat(ahb_seq_item transfer);
  if (transfer.beat_addr_q.size() == 0) begin
    transfer.beat_addr_q.push_back(transfer.haddr);
    if (transfer.direction == WRITE)
      transfer.beat_data_q.push_back(transfer.hwdata);
    else
      transfer.beat_data_q.push_back(transfer.hrdata);
  end
endfunction : normalize_single_beat


function void sramc_scoreboard::compare(ahb_seq_item actual, ahb_seq_item expected);
  bit [31:0] mask;

  case (actual.access_size)
    BYTE:     mask = 32'h0000_00ff;
    HALFWORD: mask = 32'h0000_ffff;
    default: mask = 32'hffff_ffff;
  endcase

  if (actual.beat_data_q.size() != expected.beat_data_q.size()) begin
    mismatched_beat_count++;
    `uvm_error(get_full_name(),
               $sformatf("read burst length mismatch actual=%0d expected=%0d",
                         actual.beat_data_q.size(), expected.beat_data_q.size()))
    return;
  end

  foreach (actual.beat_data_q[beat_index]) begin
    read_beat_count++;
    if ((expected.compare_enabled_q.size() <= beat_index) ||
        !expected.compare_enabled_q[beat_index]) begin
      `uvm_warning(get_full_name(),
                   $sformatf("read beat=%0d addr=%h has no expected value; skip compare",
                             beat_index, actual.beat_addr_q[beat_index]))
      continue;
    end

    if ((expected.beat_data_q[beat_index] & mask) !=
        (actual.beat_data_q[beat_index] & mask)) begin
      mismatched_beat_count++;
      `uvm_error(get_full_name(),
                 $sformatf("data mismatch beat=%0d addr=%h size=%0d exp=%h rtl=%h",
                           beat_index, actual.beat_addr_q[beat_index], actual.access_size,
                           (expected.beat_data_q[beat_index] & mask),
                           (actual.beat_data_q[beat_index] & mask)))
    end
    else begin
      matched_beat_count++;
      `uvm_info(get_full_name(),
                $sformatf("data match beat=%0d addr=%h size=%0d exp=%h rtl=%h",
                          beat_index, actual.beat_addr_q[beat_index], actual.access_size,
                          (expected.beat_data_q[beat_index] & mask),
                          (actual.beat_data_q[beat_index] & mask)), UVM_LOW)
    end
  end
endfunction : compare


function void sramc_scoreboard::report_phase(uvm_phase phase);
  `uvm_info(get_full_name(),
            $sformatf("scoreboard summary: write_beats=%0d read_beats=%0d matched_beats=%0d mismatched_beats=%0d",
                      write_beat_count, read_beat_count,
                      matched_beat_count, mismatched_beat_count),
            UVM_LOW)
endfunction : report_phase

`endif // SRAMC_SCOREBOARD_SV
